begin;
create extension if not exists pgtap with schema extensions;
select plan(43);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at)
values ('00000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','one@example.test','',now(),now()),
       ('00000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','two@example.test','',now(),now());
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select is((public.sync_push_mutations(jsonb_build_array(jsonb_build_object(
  'operation_id','10000000-0000-4000-8000-000000000001','entity_type','item','operation_type','insert',
  'record_id','20000000-0000-4000-8000-000000000001','version',1,
  'payload',jsonb_build_object('name','Bike','category','vehicle','has_odometer',true))))->'mutations_result'->0->>'status'),'accepted','item created');
select is((public.sync_push_mutations(jsonb_build_array(jsonb_build_object(
  'operation_id','10000000-0000-4000-8000-000000000001','entity_type','item','operation_type','insert',
  'record_id','20000000-0000-4000-8000-000000000001','version',1,
  'payload',jsonb_build_object('name','Bike','category','vehicle','has_odometer',true))))->'mutations_result'->0->>'status'),'accepted','retry replays exact result');
select throws_ok($$select public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000001","record_id":"20000000-0000-4000-8000-000000000001","entity_type":"item","operation_type":"insert","version":1,"payload":{"name":"Other","category":"vehicle"}}]'::jsonb)$$,'22023','Operation ID reused with different request','changed replay rejected');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000002","record_id":"20000000-0000-4000-8000-000000000001","entity_type":"item","operation_type":"update","version":3,"payload":{"name":"Bad"}}]'::jsonb)->'mutations_result'->0->>'status'),'conflict_rejected','revision conflict');
select is((select name from public.items where id='20000000-0000-4000-8000-000000000001'),'Bike','conflict did not mutate');
select throws_ok($$select public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000003","record_id":"20000000-0000-4000-8000-000000000003","entity_type":"item","operation_type":"insert","version":1,"payload":{"name":"Bad","category":"invalid"}}]'::jsonb)$$,'23514',null,'category validation');
select throws_ok($$select public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000004","record_id":"20000000-0000-4000-8000-000000000004","entity_type":"reminder","operation_type":"insert","version":1,"payload":{"item_id":"20000000-0000-4000-8000-000000000009","name":"Oil","engine_type":"usage","usage_threshold":2}}]'::jsonb)$$,'42501','Active owned item required','parent validation');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000005","record_id":"30000000-0000-4000-8000-000000000001","entity_type":"reminder","operation_type":"insert","version":1,"payload":{"item_id":"20000000-0000-4000-8000-000000000001","name":"Oil","engine_type":"usage","usage_threshold":2}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','reminder created');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000006","record_id":"40000000-0000-4000-8000-000000000001","entity_type":"progress","operation_type":"insert","version":1,"payload":{"item_id":"20000000-0000-4000-8000-000000000001","reminder_id":"30000000-0000-4000-8000-000000000001","kind":"usage","amount":1}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','progress accepted');
select is((select usage_counter from public.reminders where id='30000000-0000-4000-8000-000000000001'),1,'usage increment once');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000006","record_id":"40000000-0000-4000-8000-000000000001","entity_type":"progress","operation_type":"insert","version":1,"payload":{"item_id":"20000000-0000-4000-8000-000000000001","reminder_id":"30000000-0000-4000-8000-000000000001","kind":"usage","amount":1}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','progress retry replayed');
select is((select usage_counter from public.reminders where id='30000000-0000-4000-8000-000000000001'),1,'progress retry no duplicate');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000007","record_id":"50000000-0000-4000-8000-000000000001","entity_type":"completion","operation_type":"insert","version":2,"payload":{"item_id":"20000000-0000-4000-8000-000000000001","reminder_id":"30000000-0000-4000-8000-000000000001","completed_at":"2026-10-25T12:00:00Z","completion_date":"2026-10-25"}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','completion accepted');
select is((select count(*)::integer from public.reminder_logs),1,'one immutable history row');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000007","record_id":"50000000-0000-4000-8000-000000000001","entity_type":"completion","operation_type":"insert","version":2,"payload":{"item_id":"20000000-0000-4000-8000-000000000001","reminder_id":"30000000-0000-4000-8000-000000000001","completed_at":"2026-10-25T12:00:00Z","completion_date":"2026-10-25"}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','completion retry replayed');
select is((select count(*)::integer from public.reminder_logs),1,'completion retry does not duplicate history');
select throws_ok($$update public.reminder_logs set notes='changed'$$,'42501',null,'history not editable');
select throws_ok($$delete from public.items$$,'42501',null,'direct delete denied');
select throws_ok($$select public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000008","record_id":"60000000-0000-4000-8000-000000000001","entity_type":"preference","operation_type":"insert","version":1,"payload":{"locale":"id","time_zone":"Asia/Jakarta"}}]'::jsonb)$$,'42501','Preferences must use user ID','preference ID validated');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000009","record_id":"00000000-0000-4000-8000-000000000001","entity_type":"preference","operation_type":"insert","version":1,"payload":{"locale":"id","time_zone":"Asia/Jakarta"}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','preferences created');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-00000000000a","record_id":"20000000-0000-4000-8000-000000000001","entity_type":"item","operation_type":"archive","version":1,"payload":{}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','item archived');
select is((select count(*)::integer from public.reminder_logs),1,'archive preserves history');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-00000000000b","record_id":"20000000-0000-4000-8000-000000000001","entity_type":"item","operation_type":"delete","version":2,"payload":{}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','item tombstoned');
select ok((select deleted_at is not null from public.reminders where id='30000000-0000-4000-8000-000000000001'),'dependent reminder tombstoned');
select is((select count(*)::integer from public.reminder_logs),1,'delete retains immutable history');
select ok(exists(select 1 from pg_catalog.pg_locks where pid=pg_backend_pid() and locktype='advisory' and granted),'operation lock held until transaction ends');
select throws_ok($$select public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000010","record_id":"20000000-0000-4000-8000-000000000010","entity_type":"item","operation_type":"insert","version":1,"payload":{"name":"Rollback","category":"other"}},{"operation_id":"10000000-0000-4000-8000-000000000011","record_id":"20000000-0000-4000-8000-000000000011","entity_type":"item","operation_type":"insert","version":1,"payload":{"name":"Invalid","category":"unknown"}}]'::jsonb)$$,'23514',null,'invalid batch fails atomically');
select is((select count(*)::integer from public.items where id='20000000-0000-4000-8000-000000000010'),0,'failed batch leaves no earlier insert');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-00000000000c","record_id":"20000000-0000-4000-8000-000000000002","entity_type":"item","operation_type":"insert","version":1,"payload":{"name":"Bike 2","category":"vehicle"}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','second item inserted');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-00000000000d","record_id":"30000000-0000-4000-8000-000000000002","entity_type":"reminder","operation_type":"insert","version":1,"payload":{"item_id":"20000000-0000-4000-8000-000000000002","name":"Annual","engine_type":"time","interval_unit":"years","interval_value":1,"target_date":"2024-02-29"}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','leap-year reminder inserted');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-00000000000e","record_id":"50000000-0000-4000-8000-000000000002","entity_type":"completion","operation_type":"insert","version":1,"payload":{"item_id":"20000000-0000-4000-8000-000000000002","reminder_id":"30000000-0000-4000-8000-000000000002","completed_at":"2024-02-29T12:00:00Z","completion_date":"2024-02-29"}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','leap-year completion');
select is((select target_date::text from public.reminders where id='30000000-0000-4000-8000-000000000002'),'2025-02-28','leap day clamps in following year');
select is((public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-00000000000f","record_id":"50000000-0000-4000-8000-000000000003","entity_type":"completion","operation_type":"insert","version":2,"payload":{"item_id":"20000000-0000-4000-8000-000000000002","reminder_id":"30000000-0000-4000-8000-000000000002","completed_at":"2024-01-01T12:00:00Z","completion_date":"2024-01-01"}}]'::jsonb)->'mutations_result'->0->>'status'),'accepted','backdated completion logged');
select is((select target_date::text from public.reminders where id='30000000-0000-4000-8000-000000000002'),'2025-02-28','backdated completion does not rewind schedule');
select is(jsonb_typeof(public.sync_pull_changes(null,2)->'changes'),'array','pull result is JSON array');
select is(jsonb_array_length(public.sync_pull_changes(null,2)->'changes'),2,'pull pagination limit');
select is(jsonb_array_length(public.sync_pull_changes(public.sync_pull_changes(null,2)->'next_cursor',500)->'changes'),7,'pull keyset continuation');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select is((select count(*)::integer from public.items),0,'RLS hides other user items');
select is(jsonb_array_length(public.sync_pull_changes(null,500)->'changes'),0,'RPC pull hides other user records');
select throws_ok($$select public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000012","record_id":"20000000-0000-4000-8000-000000000001","entity_type":"item","operation_type":"update","version":2,"payload":{"name":"Stolen"}}]'::jsonb)$$,'42501','Record belongs to another user','cross-account update rejected');
select throws_ok($$select public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000013","record_id":"30000000-0000-4000-8000-000000000013","entity_type":"reminder","operation_type":"insert","version":1,"payload":{"item_id":"20000000-0000-4000-8000-000000000002","name":"Stolen","engine_type":"usage","usage_threshold":2}}]'::jsonb)$$,'42501','Active owned item required','cross-account parent rejected');
select throws_ok($$select public.sync_push_mutations('[{"operation_id":"10000000-0000-4000-8000-000000000001","record_id":"20000000-0000-4000-8000-000000000001","entity_type":"item","operation_type":"insert","version":1,"payload":{"name":"Bike","category":"vehicle","has_odometer":true}}]'::jsonb)$$,'42501','Operation belongs to another user','other account cannot replay operation');
select is((select count(*)::integer from public.reminder_logs),0,'RLS hides other user history');
select * from finish();
rollback;
